conv2d_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T,
          int THREADS,
          int OC_TILE,
          int OH_TILE,
          int OW_TILE,
          int IC_CHUNK>
__global__ void conv2d_tiled_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int OC, int Hout, int Wout,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int num_ow_tiles,
    int in_h_tile, int in_w_tile)
{
  static_assert(THREADS == OH_TILE * OW_TILE, "THREADS must equal OH_TILE * OW_TILE");

  extern __shared__ T smem_raw[];
  T* sX_ptr = smem_raw;
  T* sW_ptr = smem_raw + (size_t)IC_CHUNK * in_h_tile * in_w_tile;

  const int tid = threadIdx.x;

  const int spatial_tile = blockIdx.x;
  const int oh_tile = spatial_tile / num_ow_tiles;
  const int ow_tile = spatial_tile - oh_tile * num_ow_tiles;

  const int oc_base = blockIdx.y * OC_TILE;
  const int oh0 = oh_tile * OH_TILE;
  const int ow0 = ow_tile * OW_TILE;
  const int n = blockIdx.z;

  const int oh_l = tid / OW_TILE;
  const int ow_l = tid - oh_l * OW_TILE;
  const int oh = oh0 + oh_l;
  const int ow = ow0 + ow_l;
  const bool active = (oh < Hout) && (ow < Wout);

  const int ih_base = oh0 * stride_h - pad_h;
  const int iw_base = ow0 * stride_w - pad_w;

  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWoc = (int64_t)C * KH * KW;
  const int64_t sWc  = (int64_t)KH * KW;
  const int64_t sWkh = (int64_t)KW;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, _1{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Hout, Wout),
      make_stride(sYc, sYh, _1{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, C, KH, KW),
      make_stride(sWoc, sWc, sWkh, _1{})
  );

  Tensor sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Int<IC_CHUNK>{}, in_h_tile, in_w_tile),
      make_stride(in_h_tile * in_w_tile, in_w_tile, _1{})
  );

  // Weight tile layout keeps output-channel innermost for unrolled FMAs.
  Tensor sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<IC_CHUNK>{}, KH, KW, Int<OC_TILE>{}),
      make_stride(KH * KW * OC_TILE, KW * OC_TILE, OC_TILE, _1{})
  );

  float acc[OC_TILE];

  #pragma unroll
  for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
    const int oc = oc_base + oc_l;
    float bval = 0.0f;
    if (B != nullptr && oc < OC) {
      bval = (float)B[oc];
    }
    acc[oc_l] = bval;
  }

  for (int ic0 = 0; ic0 < C; ic0 += IC_CHUNK) {
    // Cooperative predicated load of the input halo tile for IC_CHUNK channels.
    const int x_tile_elems = IC_CHUNK * in_h_tile * in_w_tile;
    for (int idx = tid; idx < x_tile_elems; idx += THREADS) {
      const int ic_l = idx / (in_h_tile * in_w_tile);
      const int rem  = idx - ic_l * (in_h_tile * in_w_tile);
      const int r    = rem / in_w_tile;
      const int c    = rem - r * in_w_tile;

      const int ic = ic0 + ic_l;
      const int ih = ih_base + r;
      const int iw = iw_base + c;

      T v = T(0);
      if (ic < C && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        v = mX(ic, ih, iw);
      }
      sX(ic_l, r, c) = v;
    }

    // Cooperative predicated load of weights: [IC_CHUNK, KH, KW, OC_TILE].
    const int w_tile_elems = IC_CHUNK * KH * KW * OC_TILE;
    for (int idx = tid; idx < w_tile_elems; idx += THREADS) {
      const int oc_l = idx % OC_TILE;
      int rem = idx / OC_TILE;
      const int kw = rem % KW;
      rem /= KW;
      const int kh = rem % KH;
      const int ic_l = rem / KH;

      const int oc = oc_base + oc_l;
      const int ic = ic0 + ic_l;

      T v = T(0);
      if (oc < OC && ic < C) {
        v = mW(oc, ic, kh, kw);
      }
      sW(ic_l, kh, kw, oc_l) = v;
    }

    __syncthreads();

    const int rbase = oh_l * stride_h;
    const int cbase = ow_l * stride_w;

    for (int ic_l = 0; ic_l < IC_CHUNK; ++ic_l) {
      for (int kh = 0; kh < KH; ++kh) {
        const int r = rbase + kh * dil_h;
        for (int kw = 0; kw < KW; ++kw) {
          const int c = cbase + kw * dil_w;
          const float xv = (float)sX(ic_l, r, c);

          #pragma unroll
          for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
            acc[oc_l] += xv * (float)sW(ic_l, kh, kw, oc_l);
          }
        }
      }
    }

    __syncthreads();
  }

  if (active) {
    #pragma unroll
    for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
      const int oc = oc_base + oc_l;
      if (oc < OC) {
        mY(oc, oh, ow) = (T)acc[oc_l];
      }
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride_h, int stride_w,
                             int pad_h, int pad_w,
                             int dil_h, int dil_w) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) {
    TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  }

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) {
    TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  }

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, C, KH, KW]");

  const int64_t N  = x.size(0);
  const int64_t C  = x.size(1);
  const int64_t H  = x.size(2);
  const int64_t Win = x.size(3);

  const int64_t OC = w.size(0);
  const int64_t Cw = w.size(1);
  const int64_t KH = w.size(2);
  const int64_t KW = w.size(3);

  TORCH_CHECK(Cw == C, "w.size(1) must equal x.size(1)");
  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be positive");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be positive");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be non-negative");

  const int64_t Hout = (H + 2 * pad_h - dil_h * (KH - 1) - 1) / stride_h + 1;
  const int64_t Wout = (Win + 2 * pad_w - dil_w * (KW - 1) - 1) / stride_w + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  constexpr int THREADS  = 256;
  constexpr int OC_TILE  = 16;
  constexpr int OH_TILE  = 8;
  constexpr int OW_TILE  = 32;
  constexpr int IC_CHUNK = 4;

  const int in_h_tile = (OH_TILE - 1) * stride_h + (int)(KH - 1) * dil_h + 1;
  const int in_w_tile = (OW_TILE - 1) * stride_w + (int)(KW - 1) * dil_w + 1;

  const int num_ow_tiles = (int)((Wout + OW_TILE - 1) / OW_TILE);
  const int num_oh_tiles = (int)((Hout + OH_TILE - 1) / OH_TILE);

  dim3 block(THREADS);
  dim3 grid(
      (unsigned)(num_oh_tiles * num_ow_tiles),
      (unsigned)((OC + OC_TILE - 1) / OC_TILE),
      (unsigned)N
  );

  const size_t smem_bytes =
      sizeof(float) * ((size_t)IC_CHUNK * in_h_tile * in_w_tile +
                       (size_t)IC_CHUNK * KH * KW * OC_TILE);

  auto kernel = conv2d_tiled_cute_kernel<float, THREADS, OC_TILE, OH_TILE, OW_TILE, IC_CHUNK>;
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute((const void*)kernel,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem_bytes);
  }

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)OC, (int)Hout, (int)Wout,
      (int)KH, (int)KW,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      num_ow_tiles,
      in_h_tile, in_w_tile
  );

  const auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_tiled_ext",
    cpp_sources=conv2d_cpp_decl,
    cuda_sources=conv2d_cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()

        kH, kW = _pair(kernel_size)
        sH, sW = _pair(stride)
        pH, pW = _pair(padding)
        dH, dW = _pair(dilation)

        assert kH > 0 and kW > 0
        assert sH > 0 and sW > 0
        assert pH >= 0 and pW >= 0
        assert dH > 0 and dW > 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (kH, kW)
        self.stride = (sH, sW)
        self.padding = (pH, pW)
        self.dilation = (dH, dW)

        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        sH, sW = self.stride
        pH, pW = self.padding
        dH, dW = self.dilation
        return self._ext.conv2d_forward(
            x,
            self.weight,
            self.bias if self.bias is not None else None,
            sH, sW,
            pH, pW,
            dH, dW,
        )

