    const int x_tile_elems = IC_CHUNK * in_h_tile * in_w_tile;
    for (int idx = tid; idx < x_tile_elems; idx += THREADS) {
      const int ic_l = idx / (in_h_tile * in_w_tile);
      const int rem  = idx - ic_l * (in_h_tile * in_w_tile);
      const int r    = rem / in_w_tile;
      const int c    = rem - r * in_w_tile;

      const int ic = ic0 + ic_l;
      const int ih = ih_base + r;
      const int iw = iw_base + c;

      T v = T(0);
