#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T,
          int THREADS,
          int OC_TILE,
          int OH_TILE,
          int OW_TILE,
          int IC_CHUNK>
__global__ void conv2d_tiled_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int OC, int Hout, int Wout,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int num_ow_tiles,
    int in_h_tile, int in_w_tile)
{
  static_assert(THREADS == OH_TILE * OW_TILE, "THREADS must equal OH_TILE * OW_TILE");

  extern __shared__ T smem_raw[];
  T* sX_ptr = smem_raw;
  T* sW_ptr = smem_raw + (size_t)IC_CHUNK * in_h_tile * in_w_tile;

  const int tid = threadIdx.x;

  const int spatial_tile = blockIdx.x;
  const int oh_tile = spatial_tile / num_ow_tiles;
  const int ow_tile = spatial_tile - oh_tile * num_ow_tiles;

  const int oc_base = blockIdx.y * OC_TILE;
  const int oh0 = oh_tile * OH_TILE;
  const int ow0 = ow_tile * OW_TILE;
  const int n = blockIdx.z;

  const int oh_l = tid / OW_TILE;
  const int ow_l = tid - oh_l * OW_TILE;
  const int oh = oh0 + oh_l;
  const int ow = ow0 + ow_l;
  const bool active = (oh < Hout) && (ow < Wout);

  const int ih_base = oh0 * stride_h - pad_h;
  const int iw_base = ow0 * stride_w - pad_w;

  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWoc = (int64_t)C * KH * KW;
  const int64_t sWc  = (int64_t)KH * KW;
  const int64_t sWkh = (int64_t)KW;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, _1{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Hout, Wout),
      make_stride(sYc, sYh, _1{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, C, KH, KW),
      make_stride(sWoc, sWc, sWkh, _1{})
  );

  Tensor sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Int<IC_CHUNK>{}, in_h_tile, in_w_tile),
      make_stride(in_h_tile * in_w_tile, in_w_tile, _1{})
  );

  // Weight tile layout keeps output-channel innermost for unrolled FMAs.
  Tensor sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<IC_CHUNK>{}, KH, KW, Int<OC_TILE>{}),
      make_stride(KH * KW * OC_TILE, KW * OC_TILE, OC_TILE, _1{})
  );

  float acc[OC_TILE];

  #pragma unroll
  for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
    const int oc = oc_base + oc_l;
    float bval = 0.0f;
    if (B != nullptr && oc < OC) {
      bval = (float)B[oc];
    }
    acc[oc_l] = bval;
  }

  for (int ic0 = 0; ic0 < C; ic0 += IC_CHUNK) {
    // Cooperative predicated load of the input halo tile for IC_CHUNK channels.
    const int x_tile_elems = IC_CHUNK * in_h_tile * in_w_tile;
    for (int idx = tid; idx < x_tile_elems; idx += THREADS) {
      const int ic_l = idx / (in_h_tile * in_w_tile);
      const int rem  = idx - ic_l * (in_h_tile * in_w_tile);
      const int r    = rem / in_w_tile;
      const int c    = rem - r * in_w_tile;

      const int ic = ic0 + ic_l;
      const int ih = ih_base + r;
      const int iw = iw_base + c;

      T v = T(0);
      if (ic < C && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
