      }
      sX(ic_l, r, c) = v;
    }

    // Cooperative predicated load of weights: [IC_CHUNK, KH, KW, OC_TILE].
    const int w_tile_elems = IC_CHUNK * KH * KW * OC_TILE;
    for (int idx = tid; idx < w_tile_elems; idx += THREADS) {
      const int oc_l = idx % OC_TILE;
      int rem = idx / OC_TILE;
      const int kw = rem % KW;
      rem /= KW;
      const int kh = rem % KH;
      const int ic_l = rem / KH;

      const int oc = oc_base + oc_l;
      const int ic = ic0 + ic_l;

      T v = T(0);
      if (oc < OC && ic < C) {
        v = mW(oc, ic, kh, kw);
      }
      sW(ic_l, kh, kw, oc_l) = v;
    }

